const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // The question asks for a future date (Nov 21, 2024). The VIIRS DNB data is not available for the future.
  // This analysis will use the latest available data for the same month, which is November 2023,
  // to provide a representative comparison of nighttime light intensity.
  const grindavik = ee.Geometry.Point([-22.4418, 63.8424]);
  const reykjavik = ee.Geometry.Point([-21.9426, 64.1466]);
  const dateStart = '2023-11-01';
  const dateEnd = '2023-11-30';

  // 2. Data Acquisition & Check
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate(dateStart, dateEnd)
    .select('avg_rad');

  const imageCount = viirsCollection.size().getInfo();
  if (imageCount === 0) {
    console.log(`No VIIRS images found for November 2023.`);
    console.log('A: No');
    return;
  }

  const image = viirsCollection.first();
  console.log(`VIIRS images for Nov 2023: ${imageCount}`);

  // 3. Processing & Calculation
  // Extract the average radiance value for each point location.
  // Using a small scale (e.g., 30) to get a more precise value at the point,
  // as the native resolution is ~750m.
  const grindavikLights = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: grindavik,
    scale: 30,
    maxPixels: 1e9
  }).get('avg_rad');

  const reykjavikLights = image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: reykjavik,
    scale: 30,
    maxPixels: 1e9
  }).get('avg_rad');

  // Server-side to client-side
  const grindavikVal = grindavikLights.getInfo();
  const reykjavikVal = reykjavikLights.getInfo();

  // 4. Validation & Final Answer
  if (grindavikVal === null || reykjavikVal === null) {
    console.log(`Calculation failed. Grindavik: ${grindavikVal}, Reykjavik: ${reykjavikVal}`);
    console.log('C3');
    return;
  }

  console.log(`Grindavík Nighttime Light Intensity (avg_rad): ${grindavikVal.toFixed(2)}`);
  console.log(`Reykjavík Nighttime Light Intensity (avg_rad): ${reykjavikVal.toFixed(2)}`);

  if (grindavikVal > reykjavikVal) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(error => {
    console.error(error);
    console.log('D');
});
